# -*- coding: utf-8 -*-
"""Ф6-П3а: отбор кандидатов потерь из печатного скана пропусков (work/f6_ref_gap_scan*.json) → список для ручной верификации.
Исключаются: киножурналы/альманахи (k4 — проверяются отдельно), формульные записи, титроподобные строки (CREDL), строки, покрытые
аннотацией соседней записи (границы статей при неопознанных головах), сюжетные/титровые строки без формы логлайна/примечания.
python3 work/f6_ref_gap_select.py <scan.json> <catalog.json> <out.json>"""
import json, re, sys
sys.path.insert(0, 'work')
import f6_p2_lib as L
scan_path, cat_path, out_path = sys.argv[1:4]
src = open('work/f6_p3a_tail_scan.py', encoding='utf-8').read()
ns = {'re': re, 'L': L}; exec(src[src.index('JUNKLINE ='):src.index('res = []')], ns); nmap = ns['nmap']
def probes(tn):
    if len(tn) <= 14: return [tn] if len(tn) >= 6 else []
    n = max(3, min(7, len(tn) // 20)); step = (len(tn) - 14) / (n - 1) if n > 1 else 0
    return [tn[int(j * step):int(j * step) + 14] for j in range(n)]
cat = json.load(open(cat_path, encoding='utf-8'))
resl = json.load(open(scan_path, encoding='utf-8')); res = {x['cat']: x for x in resl}
K4 = re.compile(r'Фитиль|Ералаш|киносборник|Киносборник|альманах|Альманах|киножурнал|Киножурнал|Кино-крокодил|Кинокрокодил|Сборник|сборник', re.I)
FORMULA = re.compile(r'^(Содержание не установлено|Фильм не сохранился|Содержание фильма не установлено)')
CREDL = re.compile(r'^[^А-ЯЁа-яё]{0,4}(Государственн|Заслуженн|Ленинградск|Киевск|Минск|Московск|Рижск|Таллинск|Вильнюсск|Тбилисск|Ереванск|Бакинск|Ташкентск|Алма-Атинск|Кишиневск|Свердловск|Новосибирск|Красноярск|Ростовск|Одесск|Литовск|Латвийск|Эстонск|Грузинск|Армянск|Азербайджанск|Узбекск|Казахск|Белорусск|Украинск|Молдавск|Республиканск|Эстрадн|Симфоническ|Академическ|Оркестр|Ансамбл|Хор\b|Хор |Вокальн|Инструментальн|Камерн|Большой (симфон|детск|хор|оркестр)|Русск(ий|ая) (народн|хор)|Народн|Детск(ий|ая) (хор|ансамбл|студи)|Концертн|Джаз|Рок-|Творческое объединение|Художественный руководитель|Худ\.? ?руководитель|Текст (от автора |за кадром |читает)|Стихи .{0,40}чита|Песн[июя]|Авт\. (пьесы|стихов|текст)|Автор и исполнитель|Автор (текста|стихов|музыки|песен)|Ведущ(ий|ая|ие)|Диктор|Гл\. (дир|ред|консульт)|Комб\. съемки|Ассис|Реж\b|Реж\.|Худ\.|Рисунки|Мультипликац|Кукольн(ая|ые) мультипл|Использован[аы]? (музыка|стихи|песни|мелоди|фрагмент|кадры|материалы)|Танцы|Цирковые|Коллектив|Руководитель|В (съемках|съемке|массовых|воздушных|фильме (участв|снимал|снимаются|использ|звучат|звучит|принимал)|картине (участв|снимал|использ|звучат)|эпизодах|исполнении|концерте|ролях|роли)|Съемочная группа|Съемочный коллектив|Киногруппа|Участвует|Участвуют|Исполняет|Исполнител|Солист|Дирижер|Балетмейстер|Пост\. (танц|трюк)|Постановщик|Трюк|Каскадер|Консульт|Ред\.|Дир\. картины|Звукоопер|Композ|Опер\.|Монтаж|Куклы|Кукловод|Актеры|Роли|Дубл|Русский текст|Перевод|Синхронн|Автор русского|Пролог|Эпилог|Вокализ|Романс|Мелоди|Музык[аи] |Запись музыки|При участии|Партии|Куплеты|Частушки|Хореограф|Фехтован|Пиротехн|Мастер|Инженер|Адм\.|Директор|Генеральный|Телефон|Компьютерный|Отпечатано|Сдано в|Подписано|Тираж|Формат|Заказ|Цена|Редактор|Корректор|Технический|Художественн(ый|ое) оформлен|ИБ №|ЛР №|Издательство|Госфильмофонд|Всесоюзн(ый|ое) объединение|В/О|«Совинфильм|Совэкспортфильм|Роли дублируют|Фильм дублирован|Фильм озвучен|Дублирован|Озвучен|Библиограф|Лит\. (обраб|консульт|запись|основа)|Научн|Военн|Оператор|Художник|Режиссер|Сценарист|Драматург|Постановка|Пост\. |Комментари|Читает|Чтец|Голос|За кадром|Текст|Стихи|Слова|Тексты песен|Авт\. сцен|Автор сцен|Сцен\.|Сценарий:|Съемки (велись|проводились|проходили|производились))', re.I)
LOG = re.compile(r'^[^А-ЯЁа-яё]{0,3}(О |Об |Обо |Фильм |Фильм-|Картина |Кинокомедия |Комедия |Драма |Повесть |Рассказ |История |Сказка |Приключени|Философск|Лирическ|Поэтическ|Сатирическ|Героическ|Романтическ|Музыкальн|Экранизация|Представление|По мотивам|По одноименн|По роману|По повести|По пьесе|По рассказ|По сказк|По произведени|По стихотворени|По новелл|В основу|На основе|На сюжет|Сценарий|Состоит из|Действие|Судьба|Жизнь|Любовь|Годы|Наши дни|Одна из|Первый|Первая|Поставлен|Демонстрация|Триптих|Дилогия|Трилогия|Продолжение|Вторая|Третья|Заключительн|Новелл|Рассказы|Три |Две |Четыре|Пять|Несколько|Эпизоды|Страницы|Хроника|Легенда|Баллада|Поэма|Притча|Быль|Кинопоэма|Кинопов|Кинороман|Киноновелл|В (РСФСР|УССР|БССР|ЗСФСР|СССР))')
An = {}
def cover(j, k, vol):
    if j not in An: An[j] = nmap(cat[j]['annotation'] or '')[0]
    tn = nmap(L.lines(vol)[k][1])[0]; pr = probes(tn)
    if not pr: return 'junk'
    h = sum(1 for p in pr if p in An[j]); return 'cov' if h * 2 >= len(pr) else ('part' if h else 'no')
out = []
for x in resl:
    if 'items' not in x: continue
    r = cat[x['cat']]
    if K4.search(r['title']) or K4.search(r['genre'] or ''): continue
    if FORMULA.match(r['annotation'] or ''): continue
    for it in x['items']:
        if it['kind'] not in ('prose', 'midline', 'part'): continue
        t = it['text']
        if CREDL.match(t): continue
        if it['kind'] != 'midline' and not LOG.match(t):
            # сюжетная проза без формы логлайна: только если длинная и не покрыта соседями (обрыв начала/конца)
            if len(re.sub(r'[^А-ЯЁа-яё]', '', t)) < 40: continue
        owners = []
        for j in range(max(0, x['cat'] - 5), min(len(cat), x['cat'] + 6)):
            if j == x['cat'] or cat[j]['source'].split('_')[0] != x['vol']: continue
            xj = res.get(j)
            if not xj or 'k1' not in xj: continue
            if not (min(xj['h2'], xj['k1']) - 3 <= it['k'] < max(xj['E'], xj['k2'] + 1)): continue
            if cover(j, it['k'], x['vol']) == 'cov': owners.append(j)
        if owners: continue
        out.append({'cat': x['cat'], 'id': r['id'], 'vol': x['vol'], 'title': r['title'], 'year': r['year'], 'k': it['k'], 'pos': it['pos'], 'kind': it['kind'], 'cov': it['cov'], 'log': bool(LOG.match(t)), 'text': t})
json.dump(out, open(out_path, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print(len(out), 'кандидатов;', len({o['cat'] for o in out}), 'записей')
for o in out: print(f"cat{o['cat']:<5d} {o['vol']:4s} «{o['title'][:32]}» {o['year']} @{o['k']} {o['pos']}-{o['kind']}[{o['cov']}]{' LOG' if o['log'] else ''} {o['text'][:120]}")
